    public static function from(Throwable $exception): string|ActionMessage
    {
        $source = $exception instanceof HasSourceMessage ? $exception->sourceMessage() : null;
        if ($source !== null) {
            return self::source($source, $exception->getMessage());
        }

        return $exception->getMessage();
    }

    public static function source(SourceMessage $source, ?string $sourceEnglish = null): string|ActionMessage
    {
        if (! isset(self::KEYS[$source->template])) {
            return $sourceEnglish ?? $source->template;
        }

        $parameters = array_map(static function (string|int|float|SourceMessage|array $value): string|int|float|ActionMessage|array {
            if ($value instanceof SourceMessage) {
                return self::source($value);
            }
            if (is_array($value)) {
                return array_map(static fn (SourceMessage $item): string|ActionMessage => self::source($item), $value);
            }

            return $value;
        }, $source->parameters);

        return new ActionMessage(self::KEYS[$source->template], $parameters, sourceEnglish: $sourceEnglish);
    }
